<?php
namespace App\Http\Controllers\HR;use App\Http\Controllers\Controller;use App\Models\{Department,Employee,JobPosition};use Illuminate\Http\Request;class EmployeeController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('hr.employees',['employees'=>Employee::with(['department','position'])->where('property_id',$p)->latest()->paginate(25),'departments'=>Department::where('property_id',$p)->where('is_active',1)->get(),'positions'=>JobPosition::where('property_id',$p)->where('is_active',1)->get()]);}public function store(Request $r){$p=auth()->user()->property_id;$d=$r->validate(['first_name'=>'required|max:100','last_name'=>'required|max:100','phone'=>'nullable|max:50','email'=>'nullable|email','department_id'=>'nullable|integer','job_position_id'=>'nullable|integer','hire_date'=>'required|date','employment_type'=>'required|max:30','basic_salary'=>'required|numeric|min:0']);$d['property_id']=$p;$d['employee_no']='EMP-'.str_pad((string)(Employee::where('property_id',$p)->count()+1),5,'0',STR_PAD_LEFT);Employee::create($d);return back()->with('success','Employee added.');}}